// crosses Biome's 1 MiB ceiling. Past it the formatter and the linter skip the
// file entirely, which means nothing written into it is checked again.
// Nothing else about them is different: `RAW_DIRECTORY` spreads these two
// consts alongside the others and every downstream read is unchanged.
//
// The type import is `import type` on purpose. `suppliers_data.ts` imports
// these consts as values, so a value import back the other way would be a
// runtime cycle; a type-only import is erased at compile time and is not.

