// ── Croatia, florists (August 2026) ───────────────────────────────────────
// 49 wedding florists and floral designers from a vetted spreadsheet of 50,
// Zagreb and the north down through Dalmatia, Istria, Kvarner and Slavonia.
//
// The fiftieth is deliberately missing. "Cvjećarnica Mozaik (Osijek)" arrived
// with the sheet's own note that one record has it closed while two 2026 ones
// have it trading, and that the business must be confirmed by phone before it
// counts. A curated card is a recommendation, so an unresolved "is this shop
// still open" is a reason to leave it out until somebody rings.
//
// A `website` is the business's own presence or nothing, same rule as the food
// batch above, and here that rule did real work. Three domains the sheet lists
// no longer resolve at all (florista.hr, cvjecarnica-viola.com,
// cvjetni-atelje-mirela.hr, all NXDOMAIN) and one is a Google `business.site`
// page from the product Google shut down, so those four carry an empty
// `website` with their phone and email intact. Where the only presence is
// social, the social wins: two Instagram profiles and one Facebook page stand
// as the website, exactly as a cake maker's Instagram does above. The rest of
// the no-site rows point nowhere rather than at a rival wedding directory.
//
// One website belonged to a different company. The sheet gave Leona Flowers &
// Weddings (Pula) zlatneruke.hr, which is a home-nursing and physiotherapy
// institution, also in Pula, also trading on "golden hands". It was caught by
// LOOKING at the photos the crawl pulled: five pictures of care work under a
// florist's name. Their Instagram is the listing's website now.
//
// 31 of the 49 ship a `gallery_urls` seed, every URL from the vendor's OWN
// site and every image opened before it was kept. That check is the whole
// reason the count is 31 and not 40: a theme demo's stock photos (divi.express
// on one Split shop's homepage), a shopping mall's aerial view standing in for
// the florist inside it, watercolour clipart, a directory's award badge and a
// vintage postcard of Šibenik all had to be thrown out, and a florist whose
// published work is entirely funeral wreaths ships no gallery at all rather
// than a wreath on a wedding card. The other 18 get the category placeholder,
// which is the honest answer until somebody finds them a photograph.
