// ── Croatia, wedding photographers (August 2026) ──────────────────────────
// 48 photographers from a vetted spreadsheet of 50, Zagreb and Zagorje down
// through Dalmatia, Istria, Kvarner and Slavonia.
//
// Two of the fifty are deliberately missing, and both for the same reason: the
// business does not present itself as a wedding photographer. GITZ Production
// (Zagreb) is a video and photo production house whose own Photo page lists
// CONCERTS, CORPORATE, DRINKS, EVENTS, FOOD, INTERIOR and INDUSTRIAL and no
// weddings at all, and the sheet's own note already conceded it is "not
// exclusively weddings". Katija Živković (Dubrovnik) publishes a portfolio of
// commercial, food, drinks, restaurant and portrait work with the word wedding
// nowhere on the site. A curated card is a recommendation, and recommending
// either to a couple would be recommending something neither one sells.
//
// `website` is the business's own presence or nothing. Two of these carry only
// a MyWed profile, which is a photographer marketplace: sending a couple there
// hands them a page of competitors, so those two carry an empty website with
// their phone intact. makarskaweddings.com is NXDOMAIN on a public resolver, so
// that one is empty too. A Pixieset or gallery.photo subdomain is the opposite
// case and stays: it is the photographer's own portfolio, merely hosted.
//
// SEVEN of these sites sit behind Cloudflare's managed challenge and answer 403
// to anything that is not a browser (a headless one is detected too). Their
// SITEMAPS are exempt from the challenge and publish <image:loc> entries
// pointing at the Pixieset CDN, which serves plainly, and robots.txt allows
// `User-agent: *` at one request a second. That path is also the honest test of
// whether the seed is worth storing at all: a URL only survived here if a plain
// server-side download fetched it, which is exactly what the gallery backfill
// does in production. Six of the seven came through; the seventh is a Pixieset
// client-gallery subdomain with no sitemap and ships no gallery.
//
// 45 of the 48 ship a `gallery_urls` seed and every image was opened before it
// was kept, which in this category matters more than in any other: a
// photographer's card IS the photographs. What that pass threw out was almost
// never a bad photo, it was the wrong subject. A "Vjenčanje" title card, a
// EPICWEDDINGS banner, a red heart logo on black, two blank frames, a portfolio
// collage, the photographer's own headshot on four different sites, a maternity
// portrait, a family session, a green-screen studio and a page of yachts and
// villas from a photographer whose wedding work lives one URL further in. The
// last one is the useful shape: the fix was `/portfolio/wedding/`, not dropping
// the vendor.
//
// `contact_email_flag: "generic"` on one row. Josip Durdov's published address
// is the wider Durdov Media desk rather than his own, which is the same reason
// a hotel group's `mice@` gets flagged: it reaches an organisation, not the
// person the card is about.
